SET statement_timeout = 240000;
BEGIN READ ONLY;
\copy (SELECT o.target_id, t.transport, lower(split_part(split_part(t.endpoint, '://', 2), '/', 1)) AS host, count(*) AS ok_reads, min(o.observed_at) AS first_ok, max(o.observed_at) AS last_ok, split_part(max(o.observed_at || ' ' || coalesce(o.protocol, '')), ' ', 2) AS last_protocol, string_agg(DISTINCT coalesce(o.protocol, ''), ',') AS protocols, min(o.observed_at) FILTER (WHERE o.protocol = '2026-07-28') AS first_modern, max(o.observed_at) FILTER (WHERE o.protocol = '2026-07-28') AS last_modern, min(o.observed_at) FILTER (WHERE o.protocol IS DISTINCT FROM '2026-07-28') AS first_legacy, max(o.observed_at) FILTER (WHERE o.protocol IS DISTINCT FROM '2026-07-28') AS last_legacy FROM observations o JOIN targets t ON t.id = o.target_id WHERE t.transport <> 'stdio' AND o.status = 'ok' AND o.observed_at >= '2026-11-02T09:00:00Z' AND o.observed_at < '2026-11-26T16:00:00Z' GROUP BY o.target_id, t.transport, t.endpoint) TO STDOUT WITH CSV HEADER
COMMIT;
